#!/usr/bin/env python3
"""Build a curated, evidence-linked phase/reference-layer inventory; never infer admission from files alone."""
from pathlib import Path
import csv,hashlib,html,json,re
R=Path(__file__).resolve().parents[1]
D=json.loads((R/'data/PROBE_LABEL_CURATION.json').read_text())
# Exact phase support for sparse Fe labels; do not present a rectangular PT grid.
fe=json.loads((R/'assets/sources/8c60d6b50c1c73_FE_SOURCE_PAIR_ADMISSION_AUDIT_20261024.json').read_text())
for row in D['rows']:
 if row['system']=='Fe':
  a=[x for x in fe['source_phase_G_candidates'] if x['phase']==row['phase']]
  row['pressure']=', '.join(str(x) for x in sorted({x['P_GPa'] for x in a}))+' GPa (discrete source states)'
  row['temperature']=', '.join(str(x) for x in sorted({x['T_K'] for x in a}))+' K; '+str(len(a))+' phase G values, not a Cartesian grid'
# Preserve the actual admission distinction recorded by different protocols.
master=list(csv.DictReader((R/'data/MASTER_FREE_ENERGY_GRID_MANIFEST.snapshot.csv').open()))
D['master_snapshot_sha256']=hashlib.sha256((R/'data/MASTER_FREE_ENERGY_GRID_MANIFEST.snapshot.csv').read_bytes()).hexdigest()
D['counts']={'systems':len({r['system'] for r in D['rows']}),'phases':len({(r['system'],r['phase']) for r in D['rows']}),'rows':len(D['rows'])}
valid=set(D['status_definitions'])
assert D['counts']=={'systems':8,'phases':19,'rows':25}
assert len({r['id'] for r in D['rows']})==25
registry={x['id']:x for x in csv.DictReader((R/'data/SOURCE_INDEX.csv').open())}
for eid,e in D['evidence'].items():
 if 'source_id' in e:
  source=registry[e['source_id']];path=R/source['href']
 else:path=R/e['href']
 assert path.is_file(),path
 assert hashlib.sha256(path.read_bytes()).hexdigest()==e['sha256'],eid
for r in D['rows']:
 for key in ['structure','phonon','thermal','g']:
  assert r[key]['status'] in valid
  assert r[key]['origin'] and r[key]['note']
 assert all(x in D['evidence'] for x in r['evidence'])
 for k in ['hamiltonian','pressure','temperature','imaginary','cost','next_step']:assert r[k]
# A fixed-volume entropy is never inferred merely from a Gibbs-temperature derivative.
D['notes']=[
 'A scoped G label does not certify a matched structure–Hessian–entropy probe pair.',
 'Fixed-volume Fvib, harmonic Svib, Cv, and the fixed-pressure derivative −dG/dT are different labels.',
 'Source effective-harmonic force constants are not automatically a static equilibrium Hessian.',
 'Imaginary-mode flags belong to a phase, reference geometry, Hamiltonian and numerical setting. A historical flag does not invalidate a different accepted layer.',
 'Rows split reference tiers and pressure domains. Repeated tiers are not additional phases or independent materials.',
 'No label is generated by the evaluated DPA in this reference inventory. Any future DPA-derived Hessian must be added as a model-derived input, not an independent reference.',
 'Reference provenance is separate from MLIP pretraining overlap; pretraining-data independence has not been established for every label.',
 'Local evidence only: no live Expanse queue or unknown remote result was inspected for this inventory.'
]
(R/'data/probe_label_availability.json').write_text(json.dumps(D,ensure_ascii=False,indent=2)+'\n')
(R/'data/probe_label_availability.js').write_text('window.FES_PROBE_LABELS='+json.dumps(D,ensure_ascii=False)+';\n')
fields=['id','system','phase','layer','pressure','temperature','hamiltonian']
for k in ['structure','phonon','thermal','g']:fields.extend([k+'_status',k+'_origin',k+'_note'])
fields+=['thermal_quantities','mode_status','imaginary','cost_short','cost','next_step','evidence']
with (R/'data/PROBE_LABEL_AVAILABILITY.csv').open('w',newline='') as f:
 w=csv.DictWriter(f,fieldnames=fields);w.writeheader()
 for r in D['rows']:
  out={k:r[k] for k in fields if k in r and k!='evidence'}
  for k in ['structure','phonon','thermal','g']:
   for suffix in ['status','origin','note']:out[k+'_'+suffix]=r[k][suffix]
  out['thermal_quantities']=r['thermal'].get('quantities','Not audited');out['evidence']='|'.join(r['evidence']);w.writerow(out)
E=html.escape
labels={'scoped':'Scoped','candidate':'Candidate','unverified':'Not verified','blocked':'Blocked','missing':'Missing'}
def cell(r,k):
 x=r[k];return '<td><span class="probe-status '+x['status']+'">'+labels[x['status']]+'</span><span class="probe-origin">'+E(x['origin'])+'</span></td>'
trs=[]
for r in D['rows']:
 trs.append('<tr data-probe-id="'+r['id']+'"><th scope="row"><button class="probe-row-button" data-probe-select="'+r['id']+'" aria-controls="probe-label-detail">'+E(r['system']+' · '+r['phase'])+'</button><small>'+E(r['layer'])+'</small></th>'+''.join(cell(r,k) for k in ['structure','phonon','thermal','g'])+'<td class="probe-state">'+E(r['pressure'])+'<small>'+E(r['hamiltonian'])+'</small></td><td><button data-probe-select="'+r['id']+'" aria-controls="probe-label-detail">Inspect '+r['id']+'</button><small>Modes: '+E(r['mode_status'])+'</small><small>Cost: '+E(r['cost_short'])+'</small></td></tr>')
section='''<section id="probe-labels" aria-labelledby="probe-label-title"><div class="eyebrow">Reference inventory · What can we probe?</div><h2 id="probe-label-title">Probe Label Availability Matrix</h2>
<p>Before probing a representation, identify the independent reference labels. Inspect each phase and reference layer. A file can exist while its physical scope or structure–label pairing remains unresolved.</p>
<div class="probe-summary"><div><b>8</b><span>Systems</span></div><div><b>19</b><span>Distinct phases</span></div><div><b>25</b><span>Phase–reference rows</span></div><div><b>Fixed V ≠ fixed P</b><span>Vibrational entropy and −∂G/∂T are separate labels</span></div></div>
<p class="small">Frozen evidence through 26 October 2026 · inventory prepared 27 October 2026. This is a local evidence audit, not a live calculation monitor. Scoped availability does not mean full physical convergence.</p>
<div class="controls"><label>System <select id="probe-system"><option value="all">All systems</option>'''+''.join('<option>'+E(x)+'</option>' for x in dict.fromkeys(r['system'] for r in D['rows']))+'''</select></label><label>Label view <select id="probe-view"><option value="all">All reference layers</option><option value="thermal">Scoped fixed-volume Fvib</option><option value="g">Scoped G(T,P)</option><option value="blocked">Blocked harmonic route</option><option value="pairing">Structure pairing still open</option></select></label><input id="probe-search" type="search" aria-label="Search probe labels" placeholder="Search phase, reference, pressure or cost"></div>
<div class="probe-legend">'''+''.join('<span><b class="probe-status '+k+'">'+v+'</b> '+E({'scoped':'Available within stated scope','candidate':'Artifact exists; acceptance open','unverified':'No matched label verified','blocked':'Physical route fails its gate','missing':'No admitted result in this tier'}[k])+'</span>' for k,v in labels.items())+'''</div>
<p id="probe-count" class="small" role="status">25 rows · 19 distinct phases · 8 systems</p><div class="tablewrap probe-table" tabindex="0" role="region" aria-label="Scrollable phase and reference label matrix"><table><caption class="small">Select a phase to inspect imaginary modes, provenance, acquisition cost and the next missing item.</caption><thead><tr><th scope="col">Phase / reference layer</th><th scope="col">Structure</th><th scope="col">Hessian / phonon</th><th scope="col">Fixed-volume vibration</th><th scope="col">G(T,P)</th><th scope="col">Pressure / Hamiltonian</th><th scope="col">Evidence & cost</th></tr></thead><tbody>'''+''.join(trs)+'''</tbody></table></div>
<div id="probe-label-detail" class="probe-detail" aria-live="polite"><p>Select a phase row for its label contract and source evidence.</p></div>
<div class="callout"><b>Independent reference does not mean a cost-free input.</b> Published reuse, independent DFT force calculations, source-fitted effective potentials and EOS-derived candidates remain separate. Target DFT or phonons add an information budget. No unmeasured GPU-hour or SU estimate is assigned here.</div>
<details><summary>How to read this matrix</summary><ul>'''+''.join('<li>'+E(x)+'</li>' for x in D['notes'])+'''</ul><p>Carbon v1 at 5 GPa and v2 at 0/10/15 GPa are scoped harmonic-QHA layers. The earlier coarse graphite center is a separate diagnostic. Ti hcp has a scoped single-phase comparison layer; it does not provide a matched hcp–bcc gap. SiO₂ source G admission does not complete a structure-to-vibration label contract. The newer Ti/Zr/Hf source master and the older scored-tail protocol retain different admission scopes.</p></details>
<div class="downloads"><a href="data/PROBE_LABEL_AVAILABILITY.csv">Download matrix CSV</a><a href="data/probe_label_availability.json">Structured labels and evidence</a><a href="PROBE_LABEL_AVAILABILITY.md">Read the inventory report</a><a href="postprocess/build_probe_matrix.py">Rebuild script</a></div></section>'''
(R/'postprocess/fragments/probe_labels.html').write_text(section)
# Idempotent insertion: also works after the main page generator runs.
h=(R/'index.html').read_text()
h=re.sub(r'<section id="probe-labels"[^>]*>.*?</section>','',h,flags=re.S)
h=h.replace('<section id="next">',section+'<section id="next">',1)
if '<a href="#probe-labels">' not in h:h=h.replace('<a href="#next">','<a href="#probe-labels">Probe labels</a><a href="#next">',1)
if 'src="data/probe_label_availability.js"' not in h:h=h.replace('</head>','<script src="data/probe_label_availability.js"></script></head>',1)
if 'assets/probe-matrix.css' not in h:h=h.replace('</head>','<link rel="stylesheet" href="assets/probe-matrix.css"></head>',1)
if 'assets/probe-matrix.js' not in h:h=h.replace('</body>','<script src="assets/probe-matrix.js"></script></body>',1)
(R/'index.html').write_text(h)
report=['# Probe Label Availability Matrix','',D['evidence_cutoff'],'',D['independence_definition'],'',D['cost_definition'],'','8 systems; 19 distinct phases; 25 phase/reference rows. This inventory adds no labels or model results.','',
 '## Interpretation','']+['- '+x for x in D['notes']]+['','## Per-phase contracts','']
for r in D['rows']:
 report+=['### '+r['id']+' · '+r['system']+' · '+r['phase']+' · '+r['layer'],'',r['pressure']+'; '+r['temperature'],r['hamiltonian'],'']
 for k in ['structure','phonon','thermal','g']:report+=['- **'+k+' — '+r[k]['status']+'**: '+r[k]['note']+' Origin: '+r[k]['origin']+'.']
 report+=['- Imaginary modes: '+r['imaginary'],'- Cost: '+r['cost'],'- Next item: '+r['next_step'],'- Evidence: '+', '.join(r['evidence']),'']
report+=['## Evidence and hash identity','']
for k,e in D['evidence'].items():report+=['- '+k+' · '+e['name']+' · SHA256 `'+e['sha256']+'`'+(' · [reference]('+e['href']+')' if e.get('href') else ' · source registry '+e['source_id'])]
report+=['','## Admission precedence','',
 'The 25 October SiO₂ scoped thermodynamic admission supersedes older source-G-pending language only for source-table evaluation; it leaves structure probes open.',
 'The frozen master admits Ti hcp comparison and carbon harmonic-QHA tiers within scope. Older pilot reports remain historical, not current admission decisions.',
 'Ti/Zr/Hf source G is available in legacy scored tails; the newer master source layer remains pending. Both facts are displayed rather than collapsed to one green status.',
 'The carbon source snapshot includes a multipressure extension with larger numerical sensitivities than the 5 GPa release. These bounds are not total physical uncertainty.',
 'No entropy or Cv table is counted merely because it could be computed from an existing spectrum. The matrix distinguishes exported labels from derivable quantities.'
]
(R/'PROBE_LABEL_AVAILABILITY.md').write_text('\n'.join(report)+'\n')
qa={'version':D['version'],'counts':D['counts'],'source_hash_checks':'pass','snapshot_sha256':D['master_snapshot_sha256'],'matrix_rows_unique':True,'curation_sha256':hashlib.sha256((R/'data/PROBE_LABEL_CURATION.json').read_bytes()).hexdigest()}
(R/'data/PROBE_LABEL_VALIDATION.json').write_text(json.dumps(qa,indent=2)+'\n')
print(json.dumps(qa,indent=2))
